def flaky(*outcomes):
    """fn() that raises/returns the given outcomes in order; calls counts invocations."""
    calls = []
    it = iter(outcomes)
    def fn():
        calls.append(1)
        o = next(it)
        if isinstance(o, BaseException):
            raise o
        return o
    return fn, calls

